def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = set()
    history = []
    rejected = []

    def parse_amount(token):
        if not token or any(c < "0" or c > "9" for c in token):
            return None
        # Parse in chunks to avoid Python's decimal string conversion limit.
        value = 0
        for start in range(0, len(token), 9):
            chunk = token[start:start + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return value

    for index, operation in enumerate(ops):
        parts = operation.split(" ")
        verb = parts[0]
        success = False

        if verb == "undo" and len(parts) == 1:
            if history:
                action = history.pop()
                kind = action[0]

                if kind == "open":
                    account = action[1]
                    del balances[account]
                    frozen.discard(account)
                elif kind == "balance":
                    balances[action[1]] = action[2]
                elif kind == "transfer":
                    balances[action[1]] = action[2]
                    balances[action[3]] = action[4]
                elif kind == "freeze":
                    frozen.remove(action[1])
                else:
                    frozen.add(action[1])
                success = True

        elif verb in ("freeze", "unfreeze") and len(parts) == 2:
            account = parts[1]
            if account in balances:
                if verb == "freeze" and account not in frozen:
                    frozen.add(account)
                    history.append(("freeze", account))
                    success = True
                elif verb == "unfreeze" and account in frozen:
                    frozen.remove(account)
                    history.append(("unfreeze", account))
                    success = True

        elif verb in ("open", "deposit", "withdraw") and len(parts) == 3:
            account = parts[1]
            amount = parse_amount(parts[2])

            if amount is not None:
                if verb == "open":
                    if account not in balances:
                        balances[account] = amount
                        history.append(("open", account))
                        success = True
                elif verb == "deposit":
                    if amount > 0 and account in balances:
                        history.append(("balance", account, balances[account]))
                        balances[account] += amount
                        success = True
                elif (
                    amount > 0
                    and account in balances
                    and account not in frozen
                    and balances[account] >= amount
                ):
                    history.append(("balance", account, balances[account]))
                    balances[account] -= amount
                    success = True

        elif verb == "transfer" and len(parts) == 4:
            source, destination = parts[1], parts[2]
            amount = parse_amount(parts[3])

            if (
                amount is not None
                and amount > 0
                and source != destination
                and source in balances
                and destination in balances
                and source not in frozen
                and balances[source] >= amount
            ):
                history.append(
                    ("transfer", source, balances[source],
                     destination, balances[destination])
                )
                balances[source] -= amount
                balances[destination] += amount
                success = True

        if not success:
            rejected.append(index)

    return balances, rejected
